const VERSION="2.7-fa04965a",CACHE="chrisos-"+VERSION,SHELL=["./","./index.html","./manifest.webmanifest","./icons/icon-192.png","./icons/icon-512.png","./icons/maskable-512.png","./icons/apple-touch-icon.png","./icons/icon.svg","./icons/favicon-32.png"];self.addEventListener("install",n=>{n.waitUntil(caches.open(CACHE).then(e=>e.addAll(SHELL)))}),self.addEventListener("activate",n=>{n.waitUntil(caches.keys().then(e=>Promise.all(e.filter(t=>t.startsWith("chrisos-")&&t!==CACHE).map(t=>caches.delete(t)))).then(()=>self.clients.claim()))}),self.addEventListener("message",n=>{n.data==="skipWaiting"&&self.skipWaiting()}),self.addEventListener("fetch",n=>{const e=n.request;if(!(e.method!=="GET"||new URL(e.url).origin!==self.location.origin)){if(e.mode==="navigate"){n.respondWith(caches.match("./index.html").then(i=>i||fetch(e)));return}n.respondWith(caches.match(e,{ignoreSearch:!0}).then(i=>i||fetch(e)))}});
